<?php declare(strict_types=1);$minutesQuery=$minutesUi['query'];$minutesState=$minutesQuery['state'];?>
<?php if($minutesUi['write']):?><nav class="segments" aria-label="<?=e($minutesText('Protokollstatus'))?>"><?php foreach(['published'=>'Freigegeben','draft'=>'Entwürfe','archived'=>'Archiv','all'=>'Alle']as$key=>$label):?><a class="<?=$minutesState===$key?'active':''?>" href="<?=e($minutesUrl(['state'=>$key]))?>"><?=e($minutesText($label))?></a><?php endforeach?></nav><?php endif?>
<form method="get" class="minutes-search"><?=hidden('view','minutes').hidden('state',$minutesState)?><label><?=e($minutesText('Protokoll suchen'))?><input class="form-control" name="q" type="search" value="<?=e($minutesQuery['q'])?>" placeholder="<?=e($minutesText('Titel durchsuchen'))?>"></label><label><?=e($minutesText('Jahr'))?><input class="form-control" name="year" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" value="<?=e($minutesQuery['year'])?>" placeholder="<?=e($minutesText('Alle Jahre'))?>"></label><button class="btn btn-outline theme-secondary"><?=e($minutesText('Suchen'))?></button></form>
<p><?=e($minutesText('{count} Protokolle · Seite {page} / {pages}',['count'=>$minutesUi['total'],'page'=>$minutesUi['page'],'pages'=>$minutesUi['pages']]))?></p>
<div class="minutes-list"><?php foreach($minutesUi['rows']as$row):?><a class="card minutes-item" href="<?=e($minutesUrl(['mid'=>$row['id']]))?>"><span class="minutes-item-icon"><?=icon('file')?></span><div><span class="minutes-date"><?=e(dateDe($row['meeting_on']))?> · <?=e($minutesText($row['source_kind']==='pdf'?'PDF-Protokoll':'Protokolle'))?></span><h2><?=e($row['title'])?></h2><span class="minutes-state minutes-state-<?=e($row['state'])?>"><?=e($minutesText($minutesStates[$row['state']]))?></span></div><span aria-hidden="true">→</span></a><?php endforeach?></div>
<?php if($minutesUi['rows']===[]):?><section class="card minutes-empty"><?=icon('file')?><h2><?=e($minutesText($minutesState==='published'?'Noch keine Protokolle freigegeben':'Keine passenden Protokolle'))?></h2><p><?=e($minutesText($minutesUi['write']?'Du kannst ein Protokoll schreiben oder als PDF hochladen.':'Hier findest du die Protokolle, sobald sie für die Mitglieder freigegeben sind.'))?></p></section><?php endif?>
<?php if($minutesUi['pages']>1):?><nav class="actions" aria-label="<?=e($minutesText('Protokollseiten'))?>"><?php foreach([-1=>'← Zurück',1=>'Weiter →']as$direction=>$label):$next=$minutesUi['page']+$direction;if($next<1||$next>$minutesUi['pages'])continue;?><a class="btn btn-outline theme-secondary" href="<?=e($minutesUrl(['state'=>$minutesState,'q'=>$minutesQuery['q'],'year'=>$minutesQuery['year'],'page'=>$next]))?>"><?=e($minutesText($label))?></a><?php endforeach?><form method="get"><?=hidden('view','minutes').hidden('state',$minutesState).hidden('q',$minutesQuery['q']).hidden('year',$minutesQuery['year'])?><label><?=e($minutesText('Seite'))?><input class="form-control" name="page" type="number" min="1" max="<?=$minutesUi['pages']?>" value="<?=$minutesUi['page']?>" required></label><button class="btn btn-outline theme-secondary"><?=e($minutesText('Seite öffnen'))?></button></form></nav><?php endif?>
